insert into saved values('controls',public.agri_command('stock_controls',pg_temp.ctx()));
insert into tap_results select is((select data->'holds'->0->>'product_name' from saved where name='controls'),'TEST liquid','Held name travels with its authorized record');
insert into tap_results select is((select data->'holds'->0->>'base_unit' from saved where name='controls'),'liter','Held stock retains its actual liquid measurement without a catalog');
insert into tap_results select is((select data->'holds'->0->>'lot' from saved where name='controls'),'TEST-LIQ-LOT','Held lot is joined to the same product');
insert into tap_results select is((select data->'holds'->0->>'expires_on' from saved where name='controls'),'2027-12-31','Actual lot expiry travels with the held record');
insert into tap_results select is((select (data->'holds'->0->>'remaining')::numeric from saved where name='controls'),0.25::numeric,'Identity details do not change held quantity');
insert into tap_results select is((select data->'issues'->0->>'base_unit' from saved where name='controls'),'liter','Pending issues retain their actual measurement');
insert into tap_results select is((select data->'issues'->0->>'lot' from saved where name='controls'),'TEST-LIQ-LOT','Pending issue lot stays attached to its own product');
insert into saved values('loss',public.agri_command('stock_loss_report',pg_temp.ctx()));
insert into tap_results select is((select jsonb_array_length(data->'rows'->0->'purchase_units') from saved where name='loss'),2,'Only this liquid product purchase units are offered');
insert into tap_results select is((select u->>'factor' from saved s cross join lateral jsonb_array_elements(s.data->'rows'->0->'purchase_units')u where s.name='loss' and u->>'id'=pg_temp.i(415)::text),'0.500000','The documented container conversion remains exact');
insert into tap_results select is((select data->'rows'->0->>'quantity' from saved where name='loss'),'0.125','Read decoration retains the canonical loss quantity');
insert into tap_results select is((select data->'totals'->>'missingLossCosts' from saved where name='loss'),'1','A known purchase unit does not invent documentary cost');
insert into tap_results select is(public.agri_command('stock_loss_report',pg_temp.ctx())->'totals'->>'documentedLossCentavos','625','The 125 ml disposal values to 625 centavos from one 500 ml container');
insert into tap_results select is((select quantity from public.branch_inventory where product_id=pg_temp.i(312) and branch_id=pg_temp.i(101) and batch_id=pg_temp.i(451)),9.75::numeric,'Reading details and recording documentary cost never deduct saleable liquid again');
insert into tap_results select is((select remaining from public.stock_holds where source_id=pg_temp.i(801)),0.125::numeric,'Exactly 125 ml remains held after measured disposal');
insert into tap_results select is((select count(*)::integer from public.payments),0,'Details and cost evidence create no cash payment');
insert into tap_results select is(jsonb_array_length(public.agri_command('stock_loss_report',pg_temp.ctx(102))->'rows'),0,'Another branch receives no loss units or identity from this branch');
